    {
        const size_t altIndex =
            BSLSTL_VARIANT_CONVERT_INDEX_OF(t_TYPE, variant);

        if (index() == altIndex) {
            bsl::get<altIndex>(*this) = BSLS_COMPILERFEATURES_FORWARD(t_TYPE,
                                        value);
        }
        else {
            Variant_Base::template baseEmplace<altIndex>(
                BSLS_COMPILERFEATURES_FORWARD(t_TYPE, value));
        }

        return *this;
    }
#else
