#if BSLSTL_VARIANT_VARIADIC_LIMIT_U >= 0
template <class t_HEAD>
bool operator<(const variant<t_HEAD>& lhs,
               const variant<t_HEAD>& rhs)
{
    typedef BloombergLP::bslstl::Variant_ImpUtil ImpUtil;

    if (rhs.valueless_by_exception()) {
        return false;
    }
    else if (lhs.valueless_by_exception()) {
        return true;
    }
    else if (lhs.index() != rhs.index()) {
        return lhs.index() < rhs.index();
    }
    return ImpUtil::LessThan(lhs, rhs);
}
#endif  // BSLSTL_VARIANT_VARIADIC_LIMIT_U >= 0

